package com.fasterxml.jackson.databind.type;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.util.ArrayBuilders;
import com.fasterxml.jackson.databind.util.ClassUtil;
import com.fasterxml.jackson.databind.util.LRUMap;
import java.io.*;
import java.lang.reflect.*;
import java.lang.reflect.ParameterizedType;
import java.lang.reflect.Type;
import java.math.*;
import java.util.*;
import java.util.List;
import java.util.Map;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class TypeFactory_constructType_TriageGen2Test {

    @Test
    public void testConstructTypeWithSimpleClass() {
        TypeFactory typeFactory = TypeFactory.defaultInstance();
        Type type = String.class;
        Class<?> contextClass = Integer.class;

        JavaType result = typeFactory.constructType(type, contextClass);

        Assert.assertNotNull(result);
        Assert.assertEquals(String.class, result.getRawClass());
    }

    @Test
    public void testConstructTypeWithParameterizedType() {
        TypeFactory typeFactory = TypeFactory.defaultInstance();

        // Create a ParameterizedType: List<String>
        Type listStringType = new ParameterizedTypeImpl(new Type[]{String.class}, List.class);
        Class<?> contextClass = Map.class;

        JavaType result = typeFactory.constructType(listStringType, contextClass);

        Assert.assertNotNull(result);
        Assert.assertEquals(List.class, result.getRawClass());
        Assert.assertEquals(1, result.getTypeParameters().length);
        Assert.assertEquals(String.class, result.getTypeParameters()[0].getRawClass());
    }

    @Test
    public void testConstructTypeWithContextClassProvidingTypeInfo() {
        TypeFactory typeFactory = TypeFactory.defaultInstance();

        // Test where the type is a TypeVariable (e.g., T) and contextClass provides the resolution
        // Since we can't easily instantiate a naked TypeVariable without a class, 
        // we use a class that extends a generic class.

        class Base<T> {}
        class Derived extends Base<String> {}

        Type typeVar = Derived.class.getSuperclass().getGenericSuperclass(); 
        // This is a ParameterizedType representing Base<String>

        JavaType result = typeFactory.constructType(typeVar, Derived.class);

        Assert.assertNotNull(result);
        Assert.assertEquals(Base.class, result.getRawClass());
        Assert.assertEquals(String.class, result.getTypeParameters()[0].getRawClass());
    }

    @Test
    public void testConstructTypeWithNullType() {
        TypeFactory typeFactory = TypeFactory.defaultInstance();

        // Depending on Jackson version, null might throw NullPointerException or return unknownType
        // Based on the signature provided, it delegates to constructType(type, constructType(contextClass))
        try {
            JavaType result = typeFactory.constructType(null, String.class);
            Assert.assertNull(result);
        } catch (NullPointerException e) {
            // Acceptable if the implementation does not handle null
        }
    }

    @Test
    public void testConstructTypeWithNullContext() {
        TypeFactory typeFactory = TypeFactory.defaultInstance();

        // contextClass being null will trigger constructType(null)
        try {
            JavaType result = typeFactory.constructType(String.class, null);
            Assert.assertNotNull(result);
            Assert.assertEquals(String.class, result.getRawClass());
        } catch (NullPointerException e) {
            // Acceptable if the implementation does not handle null
        }
    }

    @Test
    public void testConstructTypeWithArrayType() {
        TypeFactory typeFactory = TypeFactory.defaultInstance();
        Type arrayType = String[].class;
        Class<?> contextClass = Object.class;

        JavaType result = typeFactory.constructType(arrayType, contextClass);

        Assert.assertNotNull(result);
        Assert.assertTrue(result.isArrayType());
        Assert.assertEquals(String.class, result.getContentType().getRawClass());
    }

    @Test
    public void testConstructTypeWithMap() {
        TypeFactory typeFactory = TypeFactory.defaultInstance();

        // Create Map<String, Integer>
        Type mapType = new ParameterizedTypeImpl(new Type[]{String.class, Integer.class}, Map.class);

        JavaType result = typeFactory.constructType(mapType, Object.class);

        Assert.assertNotNull(result);
        Assert.assertEquals(Map.class, result.getRawClass());
        Assert.assertEquals(String.class, result.getTypeParameters()[0].getRawClass());
        Assert.assertEquals(Integer.class, result.getTypeParameters()[1].getRawClass());
    }

    /**
     * Helper class to simulate ParameterizedType since we cannot easily 
     * instantiate complex types via reflection in a unit test.
     */
    private static class ParameterizedTypeImpl implements ParameterizedType {
        private final Type[] actualTypeArguments;
        private final Class<?> rawType;

        public ParameterizedTypeImpl(Type[] actualTypeArguments, Class<?> rawType) {
            this.actualTypeArguments = actualTypeArguments;
            this.rawType = rawType;
        }

        @Override
        public Type[] getActualTypeArguments() {
            return actualTypeArguments;
        }

        @Override
        public Type getRawType() {
            return rawType;
        }

        @Override
        public Type getOwnerType() {
            return null;
        }
    }
}
